import{c as e,Q as t,j as s,m as l}from"./chunks/framework.DOi4mjdC.js";const _=JSON.parse('{"title":"AIC和AIV独立运行机制","description":"","frontmatter":{},"headers":[{"level":1,"title":"AIC和AIV独立运行机制","slug":"aic和aiv独立运行机制"},{"level":2,"title":"功能介绍","slug":"功能介绍"},{"level":2,"title":"使用场景","slug":"使用场景"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"guide/算子实践参考/SIMD算子实现/矩阵编程（高阶API）/特性场景/AIC和AIV独立运行机制.md","filePath":"guide/算子实践参考/SIMD算子实现/矩阵编程（高阶API）/特性场景/AIC和AIV独立运行机制.md"}'),n={name:"guide/算子实践参考/SIMD算子实现/矩阵编程（高阶API）/特性场景/AIC和AIV独立运行机制.md"};function r(i,a,o,p,c,m){return t(),s("div",null,[...a[0]||(a[0]=[l(`<h1 id="aic和aiv独立运行机制" tabindex="-1">AIC和AIV独立运行机制 <a class="header-anchor" href="#aic和aiv独立运行机制" aria-label="Permalink to &quot;AIC和AIV独立运行机制&quot;">​</a></h1><h2 id="功能介绍" tabindex="-1">功能介绍 <a class="header-anchor" href="#功能介绍" aria-label="Permalink to &quot;功能介绍&quot;">​</a></h2><p>AIC和AIV独立运行机制，又称双主模式。在<a href="./../../../../编程指南/硬件实现/基本架构.html#li188191010204418">分离模式</a>下，区别于MIX模式（包含矩阵计算和矢量计算）通过消息机制驱动AIC运行，双主模式为AIC和AIV独立运行代码，不依赖消息驱动，使能双主模式能够提高Matmul计算性能。默认情况下，双主模式不使能，需要通过MatmulConfig中的enableMixDualMaster参数开启。</p><h2 id="使用场景" tabindex="-1">使用场景 <a class="header-anchor" href="#使用场景" aria-label="Permalink to &quot;使用场景&quot;">​</a></h2><p>算子中的矩阵计算和矢量计算相关代码独立运行，不依赖消息驱动时，可以开启双主模式，以提高Matmul计算性能。</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li><p>该功能仅支持<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/MatmulConfig.md" target="_blank" rel="noreferrer">Norm模板</a>和<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/MatmulConfig.md" target="_blank" rel="noreferrer">MDL模板</a>。</p></li><li><p>算子核函数的类型为MIX，同时AIC核数 : AIV核数为1:1。</p></li><li><p>算子核函数的类型为MIX，同时AIC核数 : AIV核数为1:2，且A矩阵和B矩阵同时使能<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/Matmul%E4%BD%BF%E7%94%A8%E8%AF%B4%E6%98%8E.md" target="_blank" rel="noreferrer">IBSHARE</a>参数。</p></li><li><p>同一算子中所有Matmul对象的该参数取值必须保持一致。</p></li><li><p>A、B、Bias矩阵只支持从Global Memory输入。</p></li><li><p>获取矩阵计算结果只支持调用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/IterateAll.md" target="_blank" rel="noreferrer">IterateAll</a>接口输出到<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/GlobalTensor.md" target="_blank" rel="noreferrer">GlobalTensor</a>，即计算结果放置于Global Memory的地址，不能调用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/GetTensorC.md" target="_blank" rel="noreferrer">GetTensorC</a>等接口获取结果。</p></li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>完整的算子样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_libraries/00_matrix/matmul_mixdualmaster" target="_blank" rel="noreferrer">使能双主模式的算子样例</a>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 修改模板参数enableMixDualMaster=true，Norm模板开启双主模式，MDL模板使用[GetMDLConfig](https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/GetMDLConfig.md)接口获取模板参数。</span></span>
<span class="line"><span>constexpr static MatmulConfig MM_CFG = GetNormalConfig(false, false, false, BatchMode::BATCH_LESS_THAN_L1, true, IterateOrder::ORDER_M, ScheduleType::OUTER_PRODUCT, false, true/*enableMixDualMaster*/);</span></span>
<span class="line"><span>Matmul&lt;A_TYPE, B_TYPE, C_TYPE, BIAS_TYPE, MM_CFG&gt; mm;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 常规Matmul计算</span></span>
<span class="line"><span>REGIST_MATMUL_OBJ(&amp;pipe, GetSysWorkSpacePtr(), mm);</span></span>
<span class="line"><span>mm.SetTensorA(gm_a);</span></span>
<span class="line"><span>mm.SetTensorB(gm_b);</span></span>
<span class="line"><span>mm.SetBias(gm_bias);</span></span>
<span class="line"><span>mm.IterateAll(gm_c);</span></span></code></pre></div>`,10)])])}const h=e(n,[["render",r]]);export{_ as __pageData,h as default};
